```javascript
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mul, add, mix, smoothstep, normalMap, displacementMap, uniform, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Colors from spec
  const colors = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // ============ STAGE BACKDROP ============
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new THREE.MeshBasicMaterial({
    color: colors.surface,
    toneMapped: false
  });
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -2.5;
  backdrop.renderOrder = 0;
  group.add(backdrop);

  // ============ PARALLAX PLANE WITH DISPLACEMENT ============
  const planeGeo = new THREE.PlaneGeometry(2.8, 1.75, 64, 64);

  // Load textures asynchronously but return sync
  let diffuseMap = null;
  let depthMap = null;
  let texturesLoaded = false;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      diffuseMap = tex;
      diffuseMap.colorSpace = THREE.SRGBColorSpace;
      texturesLoaded = true;
      planeMat.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthMap = tex;
      depthMap.colorSpace = THREE.LinearSRGBColorSpace;
      texturesLoaded = true;
      planeMat.needsUpdate = true;
    });
  }

  // TSL displacement & material setup
  const displacementScale = uniform(0.15);
  const displacementNode = depthMap 
    ? mul(texture(depthMap), displacementScale)
    : mul(0.0);

  const positionNode = add(
    displacementMap(displacementNode),
    vec3(0, 0, 0)
  );

  const planeMat = new MeshStandardNodeMaterial({
    color: colors.paper,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    toneMapped: false
  });

  // Override position with displacement
  planeMat.positionNode = positionNode;

  if (diffuseMap) {
    planeMat.map = diffuseMap;
  }

  const plane = new THREE.Mesh(planeGeo, planeMat);
  plane.castShadow = true;
  plane.receiveShadow = true;
  plane.renderOrder = 5;
  group.add(plane);

  // ============ INTERACTIVE LIGHTING ============
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(0.5, 0.8, 1.0);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.set(2048, 2048);
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight(colors.accent, 0.8);
  rimLight.position.set(-0.8, 0.4, -1.0);
  group.add(rimLight);

  const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
  group.add(ambientLight);

  // ============ CONTACT SHADOW ============
  const shadowGeo = new THREE.CircleGeometry(2.2, 32);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.45,
    toneMapped: false
  });
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -1.0, -0.05);
  shadow.scale.set(1.0, 0.4, 1.0);
  shadow.renderOrder = 1;
  group.add(shadow);

  // ============ PARALLAX EFFECT ============
  let mouseX = 0;
  let mouseY = 0;
  const parallaxStrength = 0.08;

  const updateParallax = () => {
    plane.rotation.x = mouseY * parallaxStrength * 0.5;
    plane.rotation.y = mouseX * parallaxStrength * 0.5;
  };

  // ============ INTERACTIONS ============
  let hoverTimeline = null;
  let pressTimeline = null;

  const onHover = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(plane.position, {
      y: 0.15,
      duration: 0.7,
      ease: 'power3.out'
    }, 0);
  };

  const onHoverOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(plane.position, {
      y: 0,
      duration: 0.9,
      ease: 'power4.out'
    }, 0);
  };

  const onPress = () => {
    if (pressTimeline) pressTimeline.kill();
    pressTimeline = gsap.timeline();
    pressTimeline.to(plane.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out'
    }, 0);
  };

  const onClick = () => {
    onPress();
    ctx.emit('hub-features.select', { nodeId: config.id });

    // If data binding present for checkout URL
    if (config.dataBindings?.length > 0) {
      const checkoutBinding = config.dataBindings.find(b => 
        b.source === 'trpc.checkout.begin.checkoutUrl'
      );
      if (checkoutBinding) {
        ctx.emit('navigate', { to: checkoutBinding.target });
      }
    }
  };

  group.userData.handlers = {
    onHover,
    onHoverOut,
    onPress,
    onClick,
    updateParallax: (x, y) => {
      mouseX = x;
      mouseY = y;
      updateParallax();
    }
  };

  // ============ CLEANUP ============
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();

    planeGeo.dispose();
    planeMat.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    if (diffuseMap) diffuseMap.dispose();
    if (depthMap) depthMap.dispose();
  };

  return group;
}
